CREATE TABLE admins(id BIGSERIAL PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, email VARCHAR(180) NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE admin_sessions(token_hash CHAR(64) PRIMARY KEY, admin_id BIGINT NOT NULL REFERENCES admins, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE reset_codes(admin_id BIGINT PRIMARY KEY REFERENCES admins, code_hash CHAR(64) NOT NULL, expires_at TIMESTAMPTZ NOT NULL, sent_at TIMESTAMPTZ NOT NULL, attempts INT NOT NULL DEFAULT 0);
CREATE TABLE auth_limits(identity_hash CHAR(64) PRIMARY KEY, failures INT NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE SEQUENCE card_number START 1;
CREATE TABLE cohorts(program VARCHAR(2) NOT NULL CHECK(program IN ('AT','CT','DT')), cohort INT NOT NULL CHECK(cohort BETWEEN 1 AND 99), intake_year INT NOT NULL, PRIMARY KEY(program,cohort));
CREATE TABLE cards(card_id VARCHAR(16) PRIMARY KEY, public_key TEXT NOT NULL UNIQUE, student_code VARCHAR(8) UNIQUE, citizen_token CHAR(64) UNIQUE, profile_enc TEXT, photo_enc TEXT, class_name VARCHAR(12), program VARCHAR(2), cohort INT, intake_year INT, birth_year INT, profile_version BIGINT NOT NULL DEFAULT 0, pending_enc TEXT, pending_hash CHAR(64), status VARCHAR(30) NOT NULL CHECK(status IN ('PROVISIONING','ACTIVE','PENDING_UPDATE')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX cards_filter ON cards(program,class_name,birth_year,intake_year);
CREATE TABLE menu_items(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL, category VARCHAR(50) NOT NULL, price BIGINT NOT NULL CHECK(price>0), available BOOLEAN NOT NULL DEFAULT true);
INSERT INTO menu_items(name,category,price) VALUES ('Cơm gà','Cơm',35000),('Cơm sườn','Cơm',35000),('Cơm trứng','Cơm',25000),('Bún thịt nướng','Món nước',30000),('Phở bò','Món nước',35000),('Bánh mì','Ăn nhẹ',20000),('Nước suối','Đồ uống',10000),('Trà đào','Đồ uống',15000),('Sữa đậu nành','Đồ uống',10000);
CREATE TABLE invoices(id BIGSERIAL PRIMARY KEY, card_id VARCHAR(16) NOT NULL REFERENCES cards, student_code VARCHAR(8) NOT NULL, name_enc TEXT NOT NULL, total BIGINT NOT NULL CHECK(total>0), status VARCHAR(20) NOT NULL CHECK(status IN ('OPEN','PAID','CANCELLED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE invoice_lines(invoice_id BIGINT NOT NULL REFERENCES invoices,item_id BIGINT NOT NULL REFERENCES menu_items,name VARCHAR(120) NOT NULL,quantity INT NOT NULL CHECK(quantity BETWEEN 1 AND 99),unit_price BIGINT NOT NULL CHECK(unit_price>0),PRIMARY KEY(invoice_id,item_id));
CREATE TABLE topups(id BIGSERIAL PRIMARY KEY,card_id VARCHAR(16) NOT NULL REFERENCES cards,reference VARCHAR(25) NOT NULL UNIQUE,amount BIGINT NOT NULL CHECK(amount>0),status VARCHAR(30) NOT NULL CHECK(status IN ('WAITING_BANK','BANK_RECEIVED','CREDITED','EXPIRED','REVIEW')),expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE bank_events(provider_id VARCHAR(100) PRIMARY KEY,bank_reference VARCHAR(150) NOT NULL UNIQUE,account_token CHAR(64) NOT NULL,amount BIGINT NOT NULL,description VARCHAR(500) NOT NULL,topup_id BIGINT UNIQUE REFERENCES topups,result VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE wallet_operations(id BIGSERIAL PRIMARY KEY,card_id VARCHAR(16) NOT NULL REFERENCES cards,kind VARCHAR(10) NOT NULL CHECK(kind IN ('CREDIT','DEBIT')),amount BIGINT NOT NULL CHECK(amount>0),topup_id BIGINT REFERENCES topups,invoice_id BIGINT REFERENCES invoices,status VARCHAR(20) NOT NULL CHECK(status IN ('PENDING','APPLIED','FAILED')),receipt TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_pending_wallet_per_card ON wallet_operations(card_id) WHERE status='PENDING';
CREATE UNIQUE INDEX one_invoice_payment ON wallet_operations(invoice_id) WHERE status<>'FAILED';
CREATE UNIQUE INDEX one_topup_credit ON wallet_operations(topup_id) WHERE status<>'FAILED';
CREATE TABLE audit_log(id BIGSERIAL PRIMARY KEY,admin_id BIGINT REFERENCES admins,card_id VARCHAR(16),action VARCHAR(50) NOT NULL,result VARCHAR(40) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
